# Load existing leanCatalog.json
with open('src/lib/data/leanCatalog.json', 'r', encoding='utf-8') as f:
    existing = json.load(f)

existing_ids = {item.get('id') for item in existing}
added_count = 0

for t in additional_titles:
    if t['id'] not in existing_ids and t['imdbId'] not in existing_ids:
        raw_score = t.get('score', 8.0)
        votes = t.get('votes', 100000)
        item = {
            "id": t['id'],
            "tmdbId": hash_code(t['id']),
            "imdbId": t['imdbId'],
            "type": t['type'],
            "title": t['title'],
            "originalTitle": t['title'],
            "overview": t['overview'],
            "releaseDate": t['releaseDate'],
            "runtimeMinutes": t.get('runtimeMinutes', 120),
            "status": "released",
            "originalLanguage": t['originalLanguage'],
            "originCountry": t['originCountry'],
            "posterPath": t['posterPath'],
            "backdropPath": t['backdropPath'],
            "genres": t['genres'],
            "cast": [],
            "directors": [],
            "ratings": {
                "imdb": { "score": raw_score, "votes": votes },
                "userCommunity": { "score": round(raw_score / 2, 1), "votes": 1200 },
                "bayesianScore": calculate_bayesian(votes, raw_score)
            },
            "popularity": round(raw_score * 11, 1),
            "trailerYoutubeKey": "dQw4w9WgXcQ"
        }
        existing.append(item)
        existing_ids.add(t['id'])
        added_count += 1

print(f"Added {added_count} curated international masterpieces.")
print(f"Total titles in leanCatalog now: {len(existing)}")

with open('src/lib/data/leanCatalog.json', 'w', encoding='utf-8') as f:
    json.dump(existing, f, ensure_ascii=False, indent=2)

print("Saved updated src/lib/data/leanCatalog.json")

